   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>

     <main id="main-content">
       <section class="support-card" aria-labelledby="support-title">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our team</h1>
         <p class="intro">
           Tell us how to reach you and we will follow up with help as soon as we can.
         </p>

         <form id="support-form" novalidate>
           <p class="required-note">
             Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.
           </p>

           <div class="form-field">
             <label for="full-name">
               Full name <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="full-name"
               name="fullName"
               type="text"
               autocomplete="name"
               required
               aria-describedby="full-name-error"
             >
             <p class="error-message" id="full-name-error" aria-live="polite"></p>
           </div>

           <div class="form-field">
             <label for="email">
               Email address <span class="required-marker" aria-hidden="true">*</span>
             </label>
             <input
               id="email"
               name="email"
               type="email"
               autocomplete="email"
               required
               aria-describedby="email-error"
             >
             <p class="error-message" id="email-error" aria-live="polite"></p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number <span>(optional)</span></label>
             <input
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               inputmode="tel"
               aria-describedby="phone-help phone-error"
             >
             <p class="helper-text" id="phone-help">
               Use 10 digits, with optional spaces, dashes, parentheses, or a leading + country code.
             </p>
             <p class="error-message" id="phone-error" aria-live="polite"></p>
           </div>

           <button type="submit">Send support request</button>
           <p class="form-status" id="form-status" role="status" aria-live="polite"></p>
         </form>
       </section>
     </main>

     <script>
       const form = document.querySelector("#support-form");
       const statusMessage = document.querySelector("#form-status");

       const fields = {
         fullName: {
           input: document.querySelector("#full-name"),
           error: document.querySelector("#full-name-error"),
           validate(value) {
             return value.trim() ? "" : "Error: Enter your full name.";
           },
         },
         email: {
           input: document.querySelector("#email"),
           error: document.querySelector("#email-error"),
           validate(value) {
             const trimmedValue = value.trim();

             if (!trimmedValue) {
               return "Error: Enter your email address.";
             }

             return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmedValue)
               ? ""
               : "Error: Enter a valid email address, like name@example.com.";
           },
         },
         phone: {
           input: document.querySelector("#phone"),
           error: document.querySelector("#phone-error"),
           validate(value) {
             const trimmedValue = value.trim();

             if (!trimmedValue) {
               return "";
             }

             const allowedCharacters = /^\+?[\d\s().-]+$/.test(trimmedValue);
             const digitCount = trimmedValue.replace(/\D/g, "").length;

             return allowedCharacters && digitCount >= 10 && digitCount <= 15
               ? ""
               : "Error: Enter a phone number with 10 to 15 digits using only numbers, spaces, dashes, parentheses, or a leading +.";
           },
         },
       };

       function setFieldError(field, message) {
         field.error.textContent = message;

         if (message) {
           field.input.setAttribute("aria-invalid", "true");
           field.input.setAttribute("aria-errormessage", field.error.id);
         } else {
           field.input.removeAttribute("aria-invalid");
           field.input.removeAttribute("aria-errormessage");
         }
       }

       function validateField(field) {
         const message = field.validate(field.input.value);
         setFieldError(field, message);
         return !message;
       }

       Object.values(fields).forEach((field) => {
         field.input.addEventListener("input", () => {
           validateField(field);
           statusMessage.textContent = "";
         });
       });

       form.addEventListener("submit", (event) => {
         event.preventDefault();
         statusMessage.textContent = "";

         let invalidField = null;

         Object.values(fields).forEach((field) => {
           const isValid = validateField(field);

           if (!isValid && !invalidField) {
             invalidField = field;
           }
         });

         if (invalidField) {
           invalidField.input.focus();
           return;
         }

         form.reset();
         Object.values(fields).forEach((field) => setFieldError(field, ""));
         statusMessage.textContent = "Your support request is ready to send. Thanks for reaching out.";
       });
     </script>
