function luminance(hex) {
  const values = hex.match(/[a-f0-9]{2}/gi).map((value) => parseInt(value, 16) / 255).map((value) => value <= 0.03928 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4);
  return 0.2126 * values[0] + 0.7152 * values[1] + 0.0722 * values[2];
}
function ratio(a, b) {
  const l1 = luminance(a);
  const l2 = luminance(b);
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}
const checks = [
  ['#f8fafc', '#111827', 4.5, 'body text/panel'],
  ['#b6c2d1', '#111827', 4.5, 'muted/panel'],
  ['#7dd3fc', '#111827', 4.5, 'accent/panel'],
  ['#fca5a5', '#111827', 4.5, 'error/panel'],
  ['#04111d', '#7dd3fc', 4.5, 'button text/accent'],
  ['#64748b', '#172033', 3, 'input border/input bg'],
  ['#94a3b8', '#172033', 3, 'input hover border/input bg'],
  ['#38bdf8', '#172033', 3, 'focus border/input bg'],
];
const failed = [];
for (const [fg, bg, minimum, label] of checks) {
  const value = ratio(fg, bg);
  console.log(`${label}: ${value.toFixed(2)}:1`);
  if (value < minimum) failed.push(label);
}
if (failed.length) {
  console.error(`Failed contrast checks: ${failed.join(', ')}`);
  process.exit(1);
}
